package com.bemo.hr.product.support;import jakarta.persistence.*;import lombok.Getter;import org.hibernate.annotations.TenantId;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="customer_health_snapshots")@Getter public class CustomerHealthSnapshot{@Id private String id;@TenantId@Column(name="app_id",nullable=false)private String appId;@Column(nullable=false)private int score;@Column(nullable=false,length=20)private String band;@Column(name="dimensions_json",nullable=false,length=3000)private String dimensionsJson;@Column(name="reasons_json",nullable=false,length=5000)private String reasonsJson;@Column(name="operation_id",nullable=false,length=80)private String operationId;@Column(name="calculated_by",nullable=false,length=100)private String calculatedBy;@Column(name="calculated_at",nullable=false)private Instant calculatedAt;protected CustomerHealthSnapshot(){}public CustomerHealthSnapshot(int score,String band,String dimensions,String reasons,String operation,String actor){id=UUID.randomUUID().toString();this.score=score;this.band=band;dimensionsJson=dimensions;reasonsJson=reasons;operationId=operation;calculatedBy=actor;calculatedAt=Instant.now();}}
